  { const g = (v, def) => { const n = (v === '' || v === null || v === undefined) ? NaN : Number(v); return Number.isFinite(n) ? Math.min(100, Math.max(0, n)) : def; };
    const hp = g(t.heroFadePos, 35), hh = g(t.heroFadeHard, 45), P = (n) => (Math.round(Math.min(100, Math.max(0, n)) * 10) / 10) + '%';
    const len = 70 * (1 - hh / 100) + 4, c = 25 + hp * 0.65, lv = 45 * (1 - hh / 100) + 4, cv = 58 + hp * 0.4;
    r.setProperty('--hero-h0', P(c - len / 2)); r.setProperty('--hero-hm', P(c - len / 2 + len * 0.55)); r.setProperty('--hero-h1', P(c + len / 2));
    r.setProperty('--hero-v0', P(cv - lv / 2)); r.setProperty('--hero-vm', P(cv - lv / 2 + lv * 0.55)); r.setProperty('--hero-v1', P(cv + lv / 2)); }
  { const ho = Number(t.heroImgOpacity); r.setProperty('--hero-img-o', String((Number.isFinite(ho) && t.heroImgOpacity !== '' && t.heroImgOpacity !== null ? Math.min(100, Math.max(0, ho)) : 85) / 100)); }
  document.body.classList.toggle('font-system', t.font === 'system');
  applyUserFonts(t);
  document.body.classList.toggle('anim', !!t.animations && !matchMedia('(prefers-reduced-motion: reduce)').matches);
