/* ---------- router / render ---------- */
/* Which document is this?  <html data-page="home|portfolio">.  Each page is its own HTML file with its own URL. */
const PAGE = document.documentElement.getAttribute('data-page') === 'portfolio' ? 'portfolio' : 'home';
